require_once __DIR__ . '/../Config/koneksi.php';require_once __DIR__ . '/../Config/auth.php';madin_role_required('admin');require_once __DIR__.'/_layout.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){madin_csrf_check();$nama=trim((string)($_POST['nama']??''));$email=strtolower(trim((string)($_POST['email']??'')));$old=(string)($_POST['password_lama']??'');$new=(string)($_POST['password_baru']??'');$confirm=(string)($_POST['konfirmasi_password']??'');$id=(int)$_SESSION['id_pengguna'];if($nama===''||!filter_var($email,FILTER_VALIDATE_EMAIL))$error='Nama dan email harus valid.';else{$stmt=mysqli_prepare($conn,'SELECT kata_sandi FROM pengguna WHERE id_pengguna=? AND peran="admin" LIMIT 1');mysqli_stmt_bind_param($stmt,'i',$id);mysqli_stmt_execute($stmt);$row=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));mysqli_stmt_close($stmt);if(!$row)$error='Data akun admin tidak ditemukan.';elseif($new!==''&&(!password_verify($old,$row['kata_sandi'])||strlen($new)<8||$new!==$confirm))$error='Untuk mengganti kata sandi, kata sandi lama harus benar, kata sandi baru minimal 8 karakter, dan konfirmasi harus sama.';else{if($new!==''){$hash=password_hash($new,PASSWORD_DEFAULT);$stmt=mysqli_prepare($conn,'UPDATE pengguna SET nama=?,email=?,kata_sandi=? WHERE id_pengguna=?');mysqli_stmt_bind_param($stmt,'sssi',$nama,$email,$hash,$id);}else{$stmt=mysqli_prepare($conn,'UPDATE pengguna SET nama=?,email=? WHERE id_pengguna=?');mysqli_stmt_bind_param($stmt,'ssi',$nama,$email,$id);}if(mysqli_stmt_execute($stmt)){$_SESSION['nama_pembeli']=$nama;$_SESSION['email_pembeli']=$email;mysqli_stmt_close($stmt);header('Location: pengaturan.php?msg='.rawurlencode('Profil admin berhasil diperbarui.'));exit;}else{$dbErr=mysqli_stmt_error($stmt);mysqli_stmt_close($stmt);$error=str_contains($dbErr,'Duplicate')?'Email tersebut sudah digunakan akun lain.':'Gagal menyimpan perubahan: '.$dbErr;}}}}
$id=(int)$_SESSION['id_pengguna'];$stmt=mysqli_prepare($conn,'SELECT nama,email FROM pengguna WHERE id_pengguna=? LIMIT 1');mysqli_stmt_bind_param($stmt,'i',$id);mysqli_stmt_execute($stmt);$admin=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));mysqli_stmt_close($stmt);madin_admin_header('Pengaturan Admin','pengaturan');if($error):?><div class="notice error"><?=madin_e($error)?></div><?php endif;?><div class="admin-card"><h2>Profil admin</h2><form class="admin-form" method="post"><input type="hidden" name="csrf_token" value="<?=madin_e(madin_csrf_token())?>"><div class="field"><label>Nama</label><input name="nama" required maxlength="100" value="<?=madin_e($admin['nama']??'')?>"></div><div class="field"><label>Email login</label><input type="email" name="email" required maxlength="150" value="<?=madin_e($admin['email']??'')?>"></div><div class="field full"><p style="font-size:13px;color:#777">Biarkan kolom kata sandi kosong jika tidak ingin mengubahnya.</p></div><div class="field"><label>Kata sandi lama</label><input type="password" name="password_lama" autocomplete="current-password"></div><div class="field"><label>Kata sandi baru (minimal 8 karakter)</label><input type="password" name="password_baru" minlength="8" autocomplete="new-password"></div><div class="field"><label>Konfirmasi kata sandi baru</label><input type="password" name="konfirmasi_password" minlength="8" autocomplete="new-password"></div><div class="form-actions"><button class="btn">Simpan perubahan</button></div></form></div><div class="admin-card"><h2>Informasi sistem</h2><p>Database yang digunakan: <strong>madin_baru</strong></p><p style="margin-top:8px">Pengaturan di halaman ini memperbarui profil dan kata sandi admin yang sedang login. Tidak ada konfigurasi database yang diubah.</p></div><?php madin_admin_footer();?>
